using namespace std;
​
// 通用 split 函数
vector<pair<string, string>> parseDependencies(const string &str) {
    vector<pair<string, string>> result;
    size_t start = 0, end;
    while ((end = str.find(',', start)) != string::npos) {
        string dep = str.substr(start, end - start);
        size_t mid = dep.find('-');
        result.emplace_back(dep.substr(0, mid), dep.substr(mid + 1));
        start = end + 1;
    }
    // 添加最后一个
    string dep = str.substr(start);
    size_t mid = dep.find('-');
    result.emplace_back(dep.substr(0, mid), dep.substr(mid + 1));
    return result;
}
​
// 递归传递失效状态
void dfs(unordered_map<string, bool> &serviceStatus, unordered_map<string, unordered_set<string>> &mp, const string &invalidService) {
    if (!serviceStatus[invalidService]) return;
    serviceStatus[invalidService] = false;
    for (const auto &x : mp[invalidService]) {
        dfs(serviceStatus, mp, x);
    }
}
​
int main() {
    string service, invalidService;
    getline(cin, service);
    getline(cin, invalidService);
​
    // 解析依赖关系
    vector<pair<string, string>> dependencies = parseDependencies(service);
    vector<string> invalidServiceArr;
    stringstream ss(invalidService);
    string tmp;
    while (getline(ss, tmp, ',')) {
        invalidServiceArr.push_back(tmp);
    }
​
    // 依赖关系表
    unordered_map<string, unordered_set<string>> mp;
    // 记录服务出现的顺序
    unordered_map<string, int> serviceSequence;
    // 记录服务状态
    unordered_map<string, bool> serviceStatus;
​
    for (int i = 0; i < dependencies.size(); ++i) {
        const string &serviceA = dependencies[i].first;
        const string &serviceB = dependencies[i].second;
​
        if (serviceSequence.find(serviceA) == serviceSequence.end()) {
            serviceSequence[serviceA] = i * 2;
        }
        if (serviceSequence.find(serviceB) == serviceSequence.end()) {
            serviceSequence[serviceB] = i * 2 + 1;
        }
        // 反向存储依赖关系（serviceB 故障会影响 serviceA）
        mp[serviceB].insert(serviceA);
        serviceStatus[serviceA] = true;
        serviceStatus[serviceB] = true;
    }
​
    // 递归处理所有故障服务
    for (const auto &invalid : invalidServiceArr) {
        dfs(serviceStatus, mp, invalid);
    }
​
    // 过滤正常服务
    vector<string> res;
    for (const auto &p : serviceStatus) {
        if (p.second) {
            res.push_back(p.first);
        }
    }
​
    if (res.empty()) {
        cout << ",";  // 无正常服务
        return 0;
    }
​
    // 按 `serviceSequence` 记录的顺序排序
    sort(res.begin(), res.end(), [&](const string &a, const string &b) {
        return serviceSequence[a] < serviceSequence[b];
    });
​
    // 输出
    cout << res[0];
    for (size_t i = 1; i < res.size(); ++i) {
        cout << "," << res[i];
    }
    return 0;
}
