    public static List<Map.Entry<String, String>> parseDependencies(String str) {
        List<Map.Entry<String, String>> result = new ArrayList<>();
        int start = 0, end;
        while ((end = str.indexOf(',', start)) != -1) {
            String dep = str.substring(start, end);
            int mid = dep.indexOf('-');
            result.add(new AbstractMap.SimpleEntry<>(dep.substring(0, mid), dep.substring(mid + 1)));
            start = end + 1;
        }
        // 添加最后一个
        String dep = str.substring(start);
        int mid = dep.indexOf('-');
        result.add(new AbstractMap.SimpleEntry<>(dep.substring(0, mid), dep.substring(mid + 1)));
        return result;
    }
​
    // 递归传递失效状态
    public static void dfs(Map<String, Boolean> serviceStatus, Map<String, Set<String>> mp, String invalidService) {
        if (!serviceStatus.get(invalidService)) return;
        serviceStatus.put(invalidService, false);
        if (mp.get(invalidService) == null) {
            return;
        }
        for (String x : mp.get(invalidService)) {
            dfs(serviceStatus, mp, x);
        }
    }
