    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String service = sc.nextLine();
        String invalidService = sc.nextLine();
​
        // 解析依赖关系
        List<Map.Entry<String, String>> dependencies = parseDependencies(service);
        String[] invalidServiceArr = invalidService.split(",");
​
        // 依赖关系表
        Map<String, Set<String>> mp = new HashMap<>();
        // 记录服务出现的顺序
        Map<String, Integer> serviceSequence = new HashMap<>();
        // 记录服务状态
        Map<String, Boolean> serviceStatus = new HashMap<>();
​
        for (int i = 0; i < dependencies.size(); ++i) {
            String serviceA = dependencies.get(i).getKey();
            String serviceB = dependencies.get(i).getValue();
​
            serviceSequence.putIfAbsent(serviceA, i * 2);
            serviceSequence.putIfAbsent(serviceB, i * 2 + 1);
​
            mp.computeIfAbsent(serviceB, k -> new HashSet<>()).add(serviceA);
            serviceStatus.put(serviceA, true);
            serviceStatus.put(serviceB, true);
        }
​
        // 递归处理所有故障服务
        for (String invalid : invalidServiceArr) {
            dfs(serviceStatus, mp, invalid);
        }
​
        // 过滤正常服务
        List<String> res = new ArrayList<>();
        for (Map.Entry<String, Boolean> p : serviceStatus.entrySet()) {
            if (p.getValue()) {
                res.add(p.getKey());
            }
        }
​
        if (res.isEmpty()) {
            System.out.println(",");
            return;
        }
​
        // 按 `serviceSequence` 记录的顺序排序
        res.sort(Comparator.comparingInt(serviceSequence::get));
​
        // 输出
        System.out.println(String.join(",", res));
    }
}
