package main
​
import (
    "fmt"
    "strings"
    "sort"
)
​
func parseDependencies(str string) []struct{ A, B string } {
    var result []struct{ A, B string }
    start := 0
    for {
        end := strings.Index(str[start:], ",")
        if end == -1 {
            break
        }
        dep := str[start : start+end]
        mid := strings.Index(dep, "-")
        result = append(result, struct{ A, B string }{dep[:mid], dep[mid+1:]})
        start = start + end + 1
    }
    // 添加最后一个
    dep := str[start:]
    mid := strings.Index(dep, "-")
    result = append(result, struct{ A, B string }{dep[:mid], dep[mid+1:]})
    return result
}
​
func dfs(serviceStatus map[string]bool, mp map[string]map[string]bool, invalidService string) {
    if !serviceStatus[invalidService] {
        return
    }
    serviceStatus[invalidService] = false
​
    for x := range mp[invalidService] {
        dfs(serviceStatus, mp, x)
    }
}
​
func main() {
    var service, invalidService string
    fmt.Scanln(&service)
    fmt.Scanln(&invalidService)
​
    // 解析依赖关系
    dependencies := parseDependencies(service)
    invalidServiceArr := strings.Split(invalidService, ",")
​
    // 依赖关系表
    mp := make(map[string]map[string]bool)
    // 记录服务出现的顺序
    serviceSequence := make(map[string]int)
    // 记录服务状态
    serviceStatus := make(map[string]bool)
​
    for i, dep := range dependencies {
        serviceA := dep.A
        serviceB := dep.B
​
        if _, found := serviceSequence[serviceA]; !found {
            serviceSequence[serviceA] = i * 2
        }
        if _, found := serviceSequence[serviceB]; !found {
            serviceSequence[serviceB] = i*2 + 1
        }
​
        if _, found := mp[serviceB]; !found {
            mp[serviceB] = make(map[string]bool)
        }
        mp[serviceB][serviceA] = true
        serviceStatus[serviceA] = true
        serviceStatus[serviceB] = true
    }
​
    // 递归处理所有故障服务
    for _, invalid := range invalidServiceArr {
        dfs(serviceStatus, mp, invalid)
    }
​
    // 过滤正常服务
    var res []string
    for key, value := range serviceStatus {
        if value {
            res = append(res, key)
        }
    }
​
    if len(res) == 0 {
        fmt.Println(",")
        return
    }
​
    // 按 `serviceSequence` 记录的顺序排序
    sort.Slice(res, func(i, j int) bool {
        return serviceSequence[res[i]] < serviceSequence[res[j]]
    })
​
    // 输出
    fmt.Println(strings.Join(res, ","))
}
